{"path":"about.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>About — {{BUSINESS_NAME}}</title>
  <meta name="description" content="A concise, grounded approach to daily habits and lasting routines from {{BUSINESS_NAME}}.">
  <style>
    :root{--bg:#f7efe6;--card:#fff6ee;--accent:#7a4b2a;--muted:#8b6f62;--ink:#33251f;--glass:rgba(255,255,255,0.6)}
    *{box-sizing:border-box}
    body{margin:0;font-family:system-ui,-apple-system,Segoe UI,Roboto,"Helvetica Neue",Arial;color:var(--ink);background:linear-gradient(180deg,var(--bg),#fbf7f4);line-height:1.45}
    header{position:relative;padding:28px 20px 12px;display:flex;align-items:center;justify-content:space-between}
    .brand{display:flex;gap:14px;align-items:center}
    .logo{width:56px;height:56px;border-radius:12px;background:linear-gradient(135deg,rgba(122,75,42,0.12),rgba(122,75,42,0.05));display:flex;align-items:center;justify-content:center;font-weight:700;color:var(--accent);font-size:20px}
    nav{display:flex;gap:14px}
    nav a{color:var(--muted);text-decoration:none;padding:8px 10px;border-radius:8px}
    nav a:hover{background:var(--glass)}
    main{max-width:980px;margin:18px auto;padding:24px}

    /* Hero */
    .hero{background:linear-gradient(180deg,rgba(122,75,42,0.04),transparent);padding:28px;border-radius:14px;display:grid;grid-template-columns:1fr 320px;gap:18px;align-items:start}
    .hero h1{margin:0;font-size:28px;color:var(--accent)}
    .hero p{margin:10px 0 0;color:var(--muted)}

    /* Pattern */
    .pattern-wrap{width:100%;height:100%;display:flex;align-items:center;justify-content:center}
    .card{background:var(--card);padding:16px;border-radius:12px;box-shadow:0 6px 18px rgba(50,30,20,0.06)}

    /* Process */
    .process{display:flex;gap:12px;margin-top:16px}
    .step{flex:1;padding:14px;background:#fff;border-radius:10px;border:1px solid rgba(60,30,10,0.03)}
    .step h4{margin:0 0 8px;color:var(--accent)}
    .muted{color:var(--muted);font-size:14px}

    /* Habit builder */
    .habit{margin-top:20px;display:grid;grid-template-columns:1fr 300px;gap:18px;align-items:start}
    label{display:block;font-size:13px;margin-bottom:6px;color:var(--muted)}
    input[type="text"],select,input[type="date"],textarea{width:100%;padding:10px;border-radius:8px;border:1px solid rgba(50,30,20,0.06);background:transparent}
    button{background:var(--accent);color:#fff;padding:10px 14px;border-radius:10px;border:0;cursor:pointer}
    .small{background:#fff;padding:8px;border-radius:8px;border:1px solid rgba(50,30,20,0.05)}
    .checklist{background:#fff;padding:12px;border-radius:8px;border:1px dashed rgba(122,75,42,0.12)}
    .days{display:flex;flex-direction:column;gap:6px}
    .day-row{display:flex;justify-content:space-between;align-items:center;padding:8px;border-radius:6px}
    .day-row:nth-child(odd){background:linear-gradient(90deg,rgba(122,75,42,0.02),transparent)}

    /* CTA */
    .cta{margin-top:20px;display:flex;gap:12px;align-items:center}

    footer{margin:28px 0 100px;color:var(--muted);font-size:13px;text-align:center}

    @media(max-width:820px){
      .hero{grid-template-columns:1fr}
      .habit{grid-template-columns:1fr}
      header{padding:18px}
    }
  </style>
</head>
<body>
  <header>
    <div class="brand">
      <div class="logo">WC</div>
      <div>
        <div style="font-weight:700">{{BUSINESS_NAME}}</div>
        <div style="font-size:13px;color:var(--muted)">An approach to steadying routines and lived practice</div>
      </div>
    </div>
    <nav>
      <a href="index.html">Home</a>
      <a href="about.html">Approach</a>
      <a href="services.html">Offerings</a>
      <a href="programs.html">Journeys</a>
      <a href="contact.html">Connect</a>
    </nav>
  </header>

  <main>
    <section class="hero">
      <div>
        <h1>Who I am and how I work</h1>
        <p class="muted">I map small, repeatable patterns — not fixes. Together we compose a personal rhythm that supports energy, clarity, and steady momentum without prescription. Practical, non-medical frameworks and simple habits designed for your life.</p>

        <div class="process" aria-hidden>
          <div class="step">
            <h4>Listen</h4>
            <p class="muted">We begin with the actual cadence of your days — hours, constraints, and what matters most.</p>
          </div>
          <div class="step">
            <h4>Design</h4>
            <p class="muted">A tiny set of repeatable moves that respect your context and ambitions.</p>
          </div>
          <div class="step">
            <h4>Practice</h4>
            <p class="muted">Short, intentional sessions and weekly checks to hold momentum.</p>
          </div>
        </div>

        <div class="cta">
          <a class="small" href="book.html">Reserve a conversation</a>
          <a href="contact.html"><button>{{PRIMARY_CTA_LABEL}}</button></a>
        </div>
      </div>

      <div class="card">
        <!-- Inline unique SVG pattern -->
        <svg viewBox="0 0 200 200" width="100%" height="100" preserveAspectRatio="xMidYMid meet" style="border-radius:8px">
          <defs>
            <pattern id="grain" patternUnits="userSpaceOnUse" width="10" height="10">
              <rect width="10" height="10" fill="#fff6ee"></rect>
              <path d="M0 8 L2 10" stroke="#f0e1d5" stroke-width="0.8"/>
              <path d="M3 0 L5 2" stroke="#f0e1d5" stroke-width="0.6"/>
            </pattern>
            <linearGradient id="g" x1="0" y1="0" x2="1" y2="1">
              <stop offset="0" stop-color="#fff4ec"/>
              <stop offset="1" stop-color="#f7efe6"/>
            </linearGradient>
          </defs>
          <rect width="100%" height="100%" fill="url(#g)" rx="8"></rect>
          <rect width="100%" height="100%" fill="url(#grain)" rx="8" opacity="0.8"></rect>
          <g transform="translate(18,22)">
            <circle cx="30" cy="30" r="28" fill="rgba(122,75,42,0.08)"/>
            <path d="M10 50 C28 22,52 22,70 50" stroke="#7a4b2a" stroke-width="3" fill="none" stroke-linecap="round" opacity="0.9"/>
            <text x="4" y="96" font-size="10" fill="#7a4b2a">A woven approach</text>
          </g>
        </svg>
      </div>
    </section>

    <section class="habit" aria-labelledby="habit-heading">
      <div>
        <h3 id="habit-heading">7-Day Habit Builder</h3>
        <p class="muted">Create a focused one-week practice and print a simple checklist to carry with you. No jargon — just a clear, printable plan.</p>

        <div style="margin-top:12px;display:grid;gap:8px">
          <div>
            <label for="focus">Focus (example: "Evening unwind", "Energy before noon")</label>
            <input id="focus" type="text" placeholder="Your short focus" value="Short morning ritual" />
          </div>
          <div>
            <label for="habit">Core habit (one sentence)</label>
            <input id="habit" type="text" placeholder="Eg: 5 minutes of breath + 2 stretches" value="5 minutes mindful breath + 2 stretches" />
          </div>
          <div style="display:flex;gap:8px">
            <div style="flex:1">
              <label for="difficulty">Intensity</label>
              <select id="difficulty">
                <option>Gentle</option>
                <option>Balanced</option>
                <option>Ambitious</option>
              </select>
            </div>
            <div>
              <label for="start">Start date</label>
              <input id="start" type="date" />
            </div>
          </div>

          <div style="display:flex;gap:8px;align-items:center">
            <button id="generate-habit">Make 7-Day Plan</button>
            <button id="print-check" class="small">Print checklist</button>
            <button id="export-txt" class="small">Export TXT</button>
          </div>
        </div>
      </div>

      <aside class="card check-list" style="padding:12px">
        <div class="checklist" id="checklist-preview">
          <strong class="muted">No plan yet — create one.</strong>
        </div>
      </aside>
    </section>

    <section style="margin-top:20px">
      <h3>Why this works</h3>
      <p class="muted">The goal is to select one small, repeatable move and make it reliably visible in your week. From there we layer short sessions and weekly reflections so you can adapt and keep the practice alive.</p>
    </section>

    <section style="margin-top:20px;display:flex;gap:12px;align-items:center">
      <div style="flex:1">
        <h4>Stories from practice</h4>
        <p class="muted">Clients report steadier afternoons, clearer decisions, and an easier path back to routines when days feel scattered. These are outcomes of disciplined, modest habits — not promises of cure.</p>
      </div>
      <div style="width:240px" class="small">
        <div style="font-weight:700">Ready to begin?</div>
        <div style="margin-top:8px"><a href="book.html">Schedule a short introduction</a></div>
      </div>
    </section>

    <footer>
      <div>Questions? Call {{PHONE}} or email <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></div>
    </footer>
  </main>

<script>
(function(){
  // Habit builder
  const generate = document.getElementById('generate-habit');
  const checklist = document.getElementById('checklist-preview');
  const printBtn = document.getElementById('print-check');
  const exportBtn = document.getElementById('export-txt');

  function formatDateISO(d){
    const dd = String(d.getDate()).padStart(2,'0');
    const mm = String(d.getMonth()+1).padStart(2,'0');
    const yy = d.getFullYear();
    return yy + '-' + mm + '-' + dd;
  }

  function buildDays(start, focus, habit){
    const out = [];
    for(let i=0;i<7;i++){
      const day = new Date(start);
      day.setDate(day.getDate()+i);
      out.push({label:day.toDateString(), action:habit});
    }
    return out;
  }

  generate.addEventListener('click',function(){
    const focus = document.getElementById('focus').value.trim() || 'Weekly focus';
    const habit = document.getElementById('habit').value.trim() || 'Do the chosen practice';
    const startVal = document.getElementById('start').value;
    const start = startVal ? new Date(startVal) : new Date();

    const days = buildDays(start, focus, habit);
    // Render checklist
    let html = '<div><strong>'+escapeHtml(focus)+'</strong><div class="muted" style="margin-bottom:8px">'+escapeHtml(habit)+'</div></div>';
    html += '<div class="days">';
    days.forEach((d,i)=>{
      html += '<div class="day-row">\n  <label><input type="checkbox" data-day="'+i+'"> '+escapeHtml(d.label)+' </label>\n  <span style="font-size:13px;color:#7a4b2a">'+escapeHtml(d.action)+'</span>\n</div>';
    });
    html += '</div>';
    checklist.innerHTML = html;
  });

  printBtn.addEventListener('click',function(){
    const w = window.open('', '_blank');
    w.document.write('<!doctype html><html><head><title>7-Day Checklist</title><meta charset="utf-8"></head><body style="font-family:system-ui;padding:18px">');
    w.document.write('<h3>7-Day Checklist</h3>');
    w.document.write(document.getElementById('checklist-preview').innerHTML);
    w.document.write('<script>window.onload=function(){window.print();};<\/script>');
    w.document.write('</body></html>');
    w.document.close();
  });

  exportBtn.addEventListener('click',function(){
    const focus = document.getElementById('focus').value.trim() || 'Weekly focus';
    const habit = document.getElementById('habit').value.trim() || 'Do the chosen practice';
    const startVal = document.getElementById('start').value;
    const start = startVal ? new Date(startVal) : new Date();
    const days = buildDays(start, focus, habit);
    let txt = focus + '\n' + habit + '\n\n';
    days.forEach((d,i)=>{ txt += (i+1)+'. '+d.label+' — '+d.action+'\n'; });
    const blob = new Blob([txt],{type:'text/plain'});
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url; a.download = '7-day-checklist.txt';
    document.body.appendChild(a); a.click(); a.remove();
    URL.revokeObjectURL(url);
  });

  function escapeHtml(s){ return s.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }
})();
</script>
</body>
</html>"} 
{"path":"services.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Offerings — {{BUSINESS_NAME}}</title>
  <meta name="description" content="Practical coaching services and single-session options focused on habits, routines, and small outcome-driven practices.">
  <style>
    :root{--bg:#f4efe8;--card:#fffaf6;--accent:#6b4a2f;--muted:#927a6b;--ink:#2f241f}
    *{box-sizing:border-box}
    body{margin:0;font-family:Inter,system-ui,-apple-system,Segoe UI,Roboto,"Helvetica Neue",Arial;background:linear-gradient(180deg,var(--bg),#fff);color:var(--ink)}
    header{display:flex;justify-content:space-between;align-items:center;padding:20px}
    .nav a{margin-left:12px;color:var(--muted);text-decoration:none}
    main{max-width:1000px;margin:18px auto;padding:18px}
    .hero{padding:18px;border-radius:12px;background:linear-gradient(180deg,rgba(107,74,47,0.04),transparent);display:flex;gap:16px;align-items:center}
    .hero h1{margin:0;color:var(--accent)}
    .grid{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin-top:18px}
    .service{background:var(--card);padding:14px;border-radius:12px;border:1px solid rgba(60,30,10,0.04)}
    .service h4{margin:0 0 8px;color:var(--accent)}
    .price{font-weight:700;color:var(--accent);margin-top:8px}

    /* Session Planner card */
    .planner{margin-top:18px;padding:14px;border-radius:12px;background:#fff;border:1px solid rgba(100,60,40,0.05)}
    label{display:block;font-size:13px;color:var(--muted);margin-bottom:6px}
    input,select,textarea{width:100%;padding:8px;border-radius:8px;border:1px solid rgba(0,0,0,0.06);background:transparent}
    button{background:var(--accent);color:#fff;padding:10px 12px;border-radius:10px;border:0;cursor:pointer}
    .output{white-space:pre-wrap;background:#fff;padding:12px;border-radius:8px;border:1px dashed rgba(100,60,40,0.08);margin-top:8px}

    @media(max-width:900px){.grid{grid-template-columns:1fr}header{padding:12px}}
  </style>
</head>
<body>
  <header>
    <div style="font-weight:700">{{BUSINESS_NAME}}</div>
    <nav class="nav">
      <a href="index.html">Home</a>
      <a href="about.html">Approach</a>
      <a href="services.html">Offerings</a>
      <a href="programs.html">Journeys</a>
      <a href="book.html">Reserve</a>
    </nav>
  </header>
  <main>
    <section class="hero">
      <div>
        <h1>Current Offerings</h1>
        <p style="color:var(--muted);margin-top:8px">Options shaped around outcomes, practice frequency, and support level. Choose what fits your schedule and scale up when it feels natural.</p>
      </div>
      <div style="width:260px" class="card" aria-hidden>
        <!-- small inline SVG motif -->
        <svg viewBox="0 0 120 80" width="100%" height="80">
          <rect width="100%" height="100%" rx="10" fill="#fff8f3" stroke="#f0e3db"/>
          <path d="M12 60 C40 22,80 22,108 60" stroke="#6b4a2f" stroke-width="3" fill="none" stroke-linecap="round"/>
        </svg>
      </div>
    </section>

    <section style="margin-top:16px">
      <div class="grid">
        <div class="service">
          <h4>Single Session — Clarify</h4>
          <p class="muted">A focused 50-minute exploration to map immediate next steps and a short practice to try over the following week.</p>
          <div class="price">$120 / session</div>
        </div>
        <div class="service">
          <h4>Compact Pact — Practice Plan</h4>
          <p class="muted">Three sessions over three weeks with a simple maintenance plan and two check-in notes. Good for building a routine anchor.</p>
          <div class="price">$320 / 3 sessions</div>
        </div>
        <div class="service">
          <h4>Monthly Stewardship</h4>
          <p class="muted">Ongoing monthly support with weekly short check-ins and a monthly reflective session for adjustments and planning.</p>
          <div class="price">$650 / month</div>
        </div>
      </div>
    </section>

    <section class="planner" aria-labelledby="planner-heading">
      <h3 id="planner-heading">Session Planner</h3>
      <p class="muted">Build a targeted session outline. Generate a short plaintext summary you can copy into a note or share.</p>

      <div style="display:grid;grid-template-columns:1fr 1fr;gap:8px">
        <div>
          <label for="goal">Primary goal for the session</label>
          <input id="goal" type="text" placeholder="E.g., build an evening wind-down" />
        </div>
        <div>
          <label for="length">Session length (minutes)</label>
          <select id="length"><option>30</option><option selected>50</option><option>75</option></select>
        </div>
        <div style="grid-column:1/3">
          <label for="focusAreas">Focus areas (comma separated)</label>
          <input id="focusAreas" type="text" placeholder="breath, movement, planning" />
        </div>
        <div style="grid-column:1/3">
          <label for="notes">Context notes (brief)</label>
          <textarea id="notes" rows="3" placeholder="What should the session respect? time, energy, environment"></textarea>
        </div>
      </div>

      <div style="margin-top:10px;display:flex;gap:8px">
        <button id="make-plan">Generate Plan</button>
        <button id="copy-plan" class="small">Copy summary</button>
        <button id="download-plan" class="small">Download TXT</button>
      </div>

      <div id="plan-output" class="output" aria-live="polite">No plan yet.</div>
    </section>

    <section style="margin-top:18px">
      <h3>How the planner is used</h3>
      <p class="muted">Use the outline during a session or keep it as a prompt for short practices between sessions. It creates a clear, plain-text summary — easy to archive in your notes.</p>
    </section>

    <section style="margin-top:18px;display:flex;gap:12px;align-items:center">
      <div style="flex:1">
        <h4>Next step</h4>
        <p class="muted">If this aligns, book a single session to try the plan and iterate the practice after a week.</p>
      </div>
      <div>
        <a href="book.html"><button>{{PRIMARY_CTA_LABEL}}</button></a>
      </div>
    </section>

    <footer style="margin-top:28px;color:var(--muted);font-size:13px">Contact: {{EMAIL}} • {{PHONE}}</footer>
  </main>

<script>
(function(){
  // Session Planner logic
  const makeBtn = document.getElementById('make-plan');
  const copyBtn = document.getElementById('copy-plan');
  const downloadBtn = document.getElementById('download-plan');
  const out = document.getElementById('plan-output');

  function buildPlan(){
    const goal = (document.getElementById('goal').value || '').trim();
    const length = (document.getElementById('length').value || '50');
    const areas = (document.getElementById('focusAreas').value || '').trim();
    const notes = (document.getElementById('notes').value || '').trim();

    const timestamp = new Date().toLocaleString();
    let lines = [];
    lines.push('Session Plan — '+timestamp);
    if(goal) lines.push('Goal: '+goal);
    lines.push('Length: '+length+' min');
    if(areas) lines.push('Focus areas: '+areas);
    if(notes) lines.push('Context: '+notes);
    lines.push('Outline:');
    lines.push('- Opening (2-5 min): brief check-in and anchor');
    lines.push('- Core practice ('+Math.max(5, Math.floor(length*0.5))+' min): targeted habit work');
    lines.push('- Short reflection (5 min): write a single note on next step');
    lines.push('Follow-up: one small practice to try between sessions.');

    return lines.join('\n');
  }

  makeBtn.addEventListener('click',function(){
    const text = buildPlan();
    out.textContent = text;
  });

  copyBtn.addEventListener('click',function(){
    const text = out.textContent || buildPlan();
    navigator.clipboard.writeText(text).then(()=>{
      copyBtn.textContent = 'Copied';
      setTimeout(()=> copyBtn.textContent = 'Copy summary',1200);
    }).catch(()=>{
      alert('Copy failed — select the text and copy manually.');
    });
  });

  downloadBtn.addEventListener('click',function(){
    const text = out.textContent || buildPlan();
    const blob = new Blob([text],{type:'text/plain'});
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a'); a.href = url; a.download = 'session-plan.txt';
    document.body.appendChild(a); a.click(); a.remove(); URL.revokeObjectURL(url);
  });
})();
</script>
</body>
</html>"} 
