<script>
(function(){
  // Compact 7-day challenge generator
  const gen = document.getElementById('gen-challenge');
  const out = document.getElementById('challenge-output');
  const printBtn = document.getElementById('print-challenge');

  gen.addEventListener('click',function(){
    const focus = document.getElementById('c-focus').value.trim() || 'Short practice';
    const minutes = document.getElementById('c-time').value.trim() || '5';
    const startVal = document.getElementById('c-start').value;
    const start = startVal ? new Date(startVal) : new Date();

    const days = [];
    for(let i=0;i<7;i++){
      const d = new Date(start); d.setDate(d.getDate()+i);
      days.push({label: d.toDateString(), task: focus + ' — '+minutes+' min'});
    }

    let html = '<div><strong>'+escapeHtml(focus)+'</strong> <span class="muted">('+escapeHtml(minutes)+' min/day)</span></div>';
    html += '<ol style="margin-top:8px">';
    days.forEach(d=>{ html += '<li style="margin-bottom:6px">'+escapeHtml(d.label)+': '+escapeHtml(d.task)+'</li>'; });
    html += '</ol>';
    out.innerHTML = html;
  });

  printBtn.addEventListener('click',function(){
    const w = window.open('','_blank');
    w.document.write('<!doctype html><html><head><meta charset="utf-8"><title>7-Day Challenge</title></head><body style="font-family:system-ui;padding:18px">');
    w.document.write('<h3>7-Day Challenge</h3>');
    w.document.write(document.getElementById('challenge-output').innerHTML);
    w.document.write('<script>window.onload=function(){window.print();};<\/script>');
    w.document.write('</body></html>');
    w.document.close();
  });

  function escapeHtml(s){ return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }
})();
</script>
